export const COMPANY_MIGRATIONS = [
  // 0001_initial.sql
  "CREATE TABLE users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  username TEXT NOT NULL UNIQUE COLLATE NOCASE,\n  password_hash TEXT NOT NULL,\n  password_salt TEXT NOT NULL,\n  full_name TEXT NOT NULL,\n  job_title TEXT NOT NULL,\n  role TEXT NOT NULL CHECK (role IN ('admin', 'regional_manager', 'superintendent', 'property_manager')),\n  region TEXT,\n  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE sessions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  token_hash TEXT NOT NULL UNIQUE,\n  user_id INTEGER NOT NULL,\n  actor_user_id INTEGER NOT NULL,\n  expires_at TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,\n  FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_sessions_token_hash ON sessions(token_hash);\nCREATE INDEX idx_sessions_expires_at ON sessions(expires_at);\nCREATE INDEX idx_users_role_active ON users(role, is_active);\n\n-- Passwords hashed with PBKDF2-SHA256, 100,000 iterations, 32-byte output\n-- (must match worker/security.js verifyPassword — Cloudflare Workers' edge\n-- WebCrypto caps PBKDF2 at 100,000 iterations, so this cannot go higher)\n-- plaintext seed passwords for local testing: admin/FHG-Admin-2026!,\n-- alex.kim/FHG-Manager-2026!, jordan.lee/FHG-Super-2026!,\n-- taylor.morgan/FHG-Property-2026!\nINSERT INTO users (username, password_hash, password_salt, full_name, job_title, role, region) VALUES\n  ('admin', '3f2c9dd77216ea6bd8cfce3c0514f963e8b306b07046fcc449bbce95eb1b2034', 'c0e6032d2388207c7175be50f5853563', 'Morgan Reed', 'System Administrator', 'admin', 'All regions'),\n  ('alex.kim', '602f2e8fc56ad52a82b6321e598ede14cfb4ce6b39666ffd1413f35962f7f4fe', '466e1ed7b3128649760e8bf12e6d1a9b', 'Alex Kim', 'Regional Operations Manager', 'regional_manager', 'Central Portfolio'),\n  ('jordan.lee', 'c7f6760bade20dfbfcfdb7aae817fc976319c3bccf659122309a770ef2a294bc', '79733be6bfab3720dd5efba0fd58c6d0', 'Jordan Lee', 'Superintendent', 'superintendent', 'Harbour Point'),\n  ('taylor.morgan', '0f5b955d187653c05a91154207c51c26379120bbf82a23b10ba6bf095ada1b17', 'afb39819f2165a1ec816bd90b055fc09', 'Taylor Morgan', 'Property Manager', 'property_manager', 'Lakeshore Residences');\n\nPRAGMA optimize;\n",
  // 0002_inspections.sql
  "-- Phase 2: Superintendent manual inspection entry.\n-- One building per superintendent for now (building_id on users) — Phase 6\n-- generalizes this to real registration + multi-building assignment.\n\nCREATE TABLE buildings (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  region TEXT,\n  inspection_days TEXT NOT NULL DEFAULT 'Mon,Tue,Wed,Thu,Fri',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nALTER TABLE users ADD COLUMN building_id INTEGER REFERENCES buildings(id);\n\n-- The checklist for a building's daily inspection — one row per reading.\n-- Phase 6 will let each building upload its own paper sheet and generate\n-- this table from it; for now it's seeded by hand to match the real\n-- \"Building Heating\" section of an actual Forest Hill inspection sheet.\nCREATE TABLE inspection_tags (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  system_name TEXT NOT NULL,\n  tag_no TEXT,\n  reading_type TEXT NOT NULL,\n  unit TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\n-- One row per building per day. UNIQUE enforces \"today's inspection\" being\n-- a single evolving record — save-as-draft updates it, submit locks it.\nCREATE TABLE inspection_submissions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  superintendent_id INTEGER NOT NULL REFERENCES users(id),\n  inspection_date TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'submitted')),\n  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  submitted_at TEXT,\n  notes TEXT,\n  UNIQUE (building_id, inspection_date)\n);\n\nCREATE TABLE inspection_readings (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  submission_id INTEGER NOT NULL REFERENCES inspection_submissions(id) ON DELETE CASCADE,\n  tag_id INTEGER NOT NULL REFERENCES inspection_tags(id),\n  value TEXT,\n  UNIQUE (submission_id, tag_id)\n);\n\nCREATE INDEX idx_submissions_building_date ON inspection_submissions(building_id, inspection_date);\nCREATE INDEX idx_readings_submission ON inspection_readings(submission_id);\n\nINSERT INTO buildings (name, region) VALUES ('Harbour Point', 'Central Portfolio');\n\nUPDATE users SET building_id = (SELECT id FROM buildings WHERE name = 'Harbour Point')\n  WHERE username = 'jordan.lee';\n\nINSERT INTO inspection_tags (building_id, system_name, tag_no, reading_type, unit, sort_order) VALUES\n  (1, 'Building Heating', NULL, 'Outside temperature', '°', 1),\n  (1, 'Building Heating', NULL, 'Building supply temp.', '°', 2),\n  (1, 'Building Heating', NULL, 'Building return temp.', '°', 3),\n  (1, 'Building Heating', 'Boiler: H1A', 'on/off', NULL, 4),\n  (1, 'Building Heating', 'Boiler: H1A', 'Inlet temperature', '°', 5),\n  (1, 'Building Heating', 'Boiler: H1A', 'Outlet temperature', '°', 6),\n  (1, 'Building Heating', 'Boiler: H1A', 'Inlet pressure', 'PSI', 7),\n  (1, 'Building Heating', 'Pump: P9A', 'on/off', NULL, 8),\n  (1, 'Building Heating', 'Pump: P9A', 'Pressure', 'PSI', 9);\n",
  // 0003_parameters.sql
  "-- Phase 3: Regional Manager optional parameters + green/yellow/red flagging.\n\nALTER TABLE inspection_tags ADD COLUMN value_type TEXT NOT NULL DEFAULT 'numeric'\n  CHECK (value_type IN ('numeric', 'on_off'));\nUPDATE inspection_tags SET value_type = 'on_off' WHERE reading_type = 'on/off';\n\n-- One optional row per tag. No row = \"not evaluated\" (parameters are opt-in,\n-- per the original spec: a manager doesn't have to set them).\n-- numeric tags use min_value/max_value; on_off tags use expected_value.\nCREATE TABLE inspection_parameters (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  tag_id INTEGER NOT NULL UNIQUE REFERENCES inspection_tags(id),\n  min_value REAL,\n  max_value REAL,\n  expected_value TEXT,\n  updated_by INTEGER REFERENCES users(id),\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n",
  // 0004_property_manager_building.sql
  "-- Phase 4: assign the Property Manager to a real building so their\n-- read-only view has real data. Reuses Harbour Point (the same building\n-- Jordan Lee inspects and Alex Kim oversees) rather than an empty\n-- unassigned building with no superintendent to ever submit for it.\nUPDATE users SET building_id = (SELECT id FROM buildings WHERE name = 'Harbour Point'),\n  region = 'Harbour Point'\n  WHERE username = 'taylor.morgan';\n",
  // 0005_building_registration.sql
  "-- Phase 6: building registration + AI-assisted checklist generation.\n\nALTER TABLE buildings ADD COLUMN address TEXT;\nALTER TABLE buildings ADD COLUMN created_by INTEGER REFERENCES users(id);\n\n-- A second test superintendent, unassigned to any building, so a newly\n-- registered building has someone real to assign and actually test with.\n-- Password: FHG-Super2-2026! (PBKDF2-SHA256, 100k iterations, matching\n-- worker/security.js — verified against the file below, same as every\n-- other seed account).\nINSERT INTO users (username, password_hash, password_salt, full_name, job_title, role, region) VALUES\n  ('sam.rivera', '07a18d56c5146cd2c28b31b457f4342c79f5be6cbe2af7945a98e8c4e3100b7c', 'bc8b0d850c38fd1b593ccb8a128eaad9', 'Sam Rivera', 'Superintendent', 'superintendent', NULL);\n",
  // 0006_self_registration.sql
  "-- Self-registration (Superintendent / Property Manager sign themselves up\n-- against an existing building, pending Regional Manager approval) and the\n-- draft -> live gate on newly registered buildings.\n\nALTER TABLE users ADD COLUMN status TEXT NOT NULL DEFAULT 'active'\n  CHECK (status IN ('pending', 'active', 'denied'));\nALTER TABLE users ADD COLUMN email TEXT;\nALTER TABLE users ADD COLUMN phone TEXT;\nALTER TABLE users ADD COLUMN profile_photo TEXT;\n\n-- 'registering' buildings are invisible to their assigned superintendent\n-- until a Regional Manager explicitly pushes them live.\nALTER TABLE buildings ADD COLUMN status TEXT NOT NULL DEFAULT 'active'\n  CHECK (status IN ('registering', 'active'));\n",
  // 0007_building_location.sql
  "-- Building location for the map picker (OpenStreetMap/Leaflet — no API key,\n-- no billing account, per the decision to not wait on a Google Maps key).\nALTER TABLE buildings ADD COLUMN latitude REAL;\nALTER TABLE buildings ADD COLUMN longitude REAL;\n",
  // 0008_work_orders.sql
  "-- Work orders: a Regional Manager's real tracking list, replacing the\n-- mock Exception Queue. Manager-only -- no assignment/resolution workflow\n-- on the superintendent side, per explicit scope decision.\n--\n-- Two sources:\n--  'reading'  -- auto-created when a superintendent confirms an\n--                out-of-range value as genuinely abnormal (not a typo)\n--  'flagged'  -- a superintendent raises something not tied to a specific\n--                reading (inventory, chemicals, a schedule/method question)\n--                that needs the manager's attention rather than a quick\n--                ask to a coworker\n\nCREATE TABLE work_orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  created_by INTEGER REFERENCES users(id),\n  source TEXT NOT NULL CHECK (source IN ('reading', 'flagged')),\n  category TEXT,\n  title TEXT NOT NULL,\n  description TEXT,\n  reading_tag_id INTEGER REFERENCES inspection_tags(id),\n  reading_value TEXT,\n  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved')),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  resolved_at TEXT,\n  resolved_by INTEGER REFERENCES users(id)\n);\n\nCREATE INDEX idx_work_orders_building_status ON work_orders(building_id, status);\n",
  // 0009_2fa_and_rom_registration.sql
  "-- Weekly email 2FA (via GHL) + letting Regional Operations Managers\n-- self-register too (previously only Superintendent/Property Manager could).\n\nALTER TABLE users ADD COLUMN last_2fa_verified_at TEXT;\nALTER TABLE users ADD COLUMN ghl_contact_id TEXT;\n\nCREATE TABLE two_factor_codes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  code TEXT NOT NULL,\n  pending_token TEXT NOT NULL UNIQUE,\n  expires_at TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_two_factor_codes_pending_token ON two_factor_codes(pending_token);\n",
  // 0010_om_role_and_building_world.sql
  "-- Operations Manager (OM): sees every registered building, unlike a\n-- Regional Manager (ROM) who only sees buildings they personally\n-- registered. Rather than adding a new `role` enum value (which would\n-- require rebuilding `users` -- D1 enforces FK constraints from\n-- sessions/buildings/work_orders/etc. even through the standard SQLite\n-- \"disable foreign_keys, rebuild, re-enable\" pattern; tested and confirmed\n-- it still fails at commit), OM is `role = 'regional_manager'` plus this\n-- new scope column. The app computes the displayed role name from the\n-- combination -- functionally identical to a real new role, zero risk to\n-- existing data.\nALTER TABLE users ADD COLUMN building_access TEXT NOT NULL DEFAULT 'own'\n  CHECK (building_access IN ('own', 'all'));\n\n-- Work order assignment: a manager hands something off to whoever should\n-- actually handle it (e.g. an Operations Manager specializing in that\n-- kind of issue).\nALTER TABLE work_orders ADD COLUMN assigned_to INTEGER REFERENCES users(id);\nALTER TABLE work_orders ADD COLUMN assigned_at TEXT;\n\n-- Per-building notices board: short instructions a manager posts for\n-- whoever covers that building -- separate from the daily inspection\n-- checklist itself. Editable/removable, not versioned.\nCREATE TABLE building_notices (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  created_by INTEGER REFERENCES users(id),\n  message TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_building_notices_building ON building_notices(building_id);\n",
  // 0011_command_mode.sql
  "-- Command mode: a guided, one-item-at-a-time inspection walkthrough for\n-- superintendents (manual entry, camera capture, or photo upload per\n-- reading), plus the machinery it depends on:\n--   - physical locations per building (ROM/OM-managed) so the walkthrough\n--     can be ordered by where the super actually is, and so a super can\n--     flag an item whose location wasn't set up right rather than having\n--     to backtrack mid-walk;\n--   - a per-reading \"flagged for later\" state that gates final submit;\n--   - a per-reading photo reference, so a value captured by camera keeps\n--     its evidence photo attached to that specific item.\n\nCREATE TABLE building_locations (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  name TEXT NOT NULL,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX idx_building_locations_building ON building_locations(building_id);\n\nALTER TABLE inspection_tags ADD COLUMN location_id INTEGER REFERENCES building_locations(id);\n\nALTER TABLE inspection_readings ADD COLUMN flagged INTEGER NOT NULL DEFAULT 0;\nALTER TABLE inspection_readings ADD COLUMN photo_key TEXT;\n",
  // 0012_contact_consent.sql
  "-- TCPA/CASL-style consent tracking: self-registering accounts now check a\n-- box agreeing to receive text messages and emails about their account\n-- (this is also the channel the weekly 2FA code and future notifications\n-- go out on) -- record that they agreed and when, not just that the box\n-- was checked at some point in the UI.\nALTER TABLE users ADD COLUMN contact_consent INTEGER NOT NULL DEFAULT 0;\nALTER TABLE users ADD COLUMN contact_consent_at TEXT;\n",
  // 0013_equipment_groups.sql
  "-- Equipment groups: a second, independent way to classify a checklist\n-- item beyond its physical location (building_locations). A pump living\n-- \"Upstairs\" (location) is also classified as \"Pumps\" (group); a boiler\n-- in the same room is \"Boilers\". Custom per building, same shape as\n-- building_locations on purpose.\nCREATE TABLE equipment_groups (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  name TEXT NOT NULL,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX idx_equipment_groups_building ON equipment_groups(building_id);\n\nALTER TABLE inspection_tags ADD COLUMN equipment_group_id INTEGER REFERENCES equipment_groups(id);\n",
  // 0014_reading_kind.sql
  "-- A third reading shape alongside numeric and on/off: \"hoa\" for a\n-- Hand-Off-Auto selector switch, standard on pumps/fans/motors -- the\n-- equipment can be found in Hand (forced on manually), Off, or Auto\n-- (running under automatic control), not just a plain on/off.\n--\n-- inspection_tags.value_type is CHECK-constrained to ('numeric','on_off')\n-- and D1 can't rebuild this table to widen that CHECK -- confirmed\n-- earlier: the standard SQLite rebuild pattern fails on FK constraints\n-- in D1 regardless of PRAGMA settings (same issue that blocked expanding\n-- users.role for the OM role; see migration 0010). Add a new column with\n-- the wider constraint instead and use it everywhere going forward --\n-- same approach as building_access. value_type itself is left in place,\n-- unused, rather than risk a rebuild.\nALTER TABLE inspection_tags ADD COLUMN reading_kind TEXT NOT NULL DEFAULT 'numeric'\n  CHECK (reading_kind IN ('numeric', 'on_off', 'hoa'));\nUPDATE inspection_tags SET reading_kind = value_type;\n",
  // 0015_answer_kind_and_sharing.sql
  "-- reading_kind's CHECK constraint hits the exact same D1 rebuild wall\n-- value_type did before it (see 0010, 0014) -- every future \"add a\n-- reading type\" request (this time: sprinklers reading Open/Closed) would\n-- need its own migration like this one. Stop using a CHECK on this field\n-- permanently: one more column, no constraint, validated in application\n-- code instead. Never needs to migrate again for a new type.\nALTER TABLE inspection_tags ADD COLUMN answer_kind TEXT NOT NULL DEFAULT 'numeric';\nUPDATE inspection_tags SET answer_kind = reading_kind;\n\n-- Building sharing: an Operations Manager can grant a specific Regional\n-- Manager full access to a building that ROM didn't personally register\n-- (they already see everything; this lets them extend that to a ROM at\n-- their discretion). Additive to created_by-based ownership, not a\n-- replacement -- a building can have any number of grants.\nCREATE TABLE building_managers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL REFERENCES buildings(id),\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  granted_by INTEGER REFERENCES users(id),\n  granted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE (building_id, user_id)\n);\nCREATE INDEX idx_building_managers_building ON building_managers(building_id);\nCREATE INDEX idx_building_managers_user ON building_managers(user_id);\n\n-- A superintendent's daily note for one equipment group as a whole (e.g.\n-- \"Elevator machine room: strong smell today, advised caution\") rather\n-- than per individual reading -- written inline while filling out the\n-- regular form, one per group per day.\nCREATE TABLE group_notes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  submission_id INTEGER NOT NULL REFERENCES inspection_submissions(id) ON DELETE CASCADE,\n  equipment_group_id INTEGER NOT NULL REFERENCES equipment_groups(id),\n  note TEXT NOT NULL,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE (submission_id, equipment_group_id)\n);\nCREATE INDEX idx_group_notes_submission ON group_notes(submission_id);\n",
  // 0016_delete_workflow_and_classification.sql
  "-- Buildings: a request/approve delete workflow with a 30-day-kept soft\n-- delete, instead of a Regional/Operations Manager's delete being instant\n-- and permanent. buildings.status stays CHECK-constrained to\n-- ('registering', 'active') on purpose (see worker/access.js's notes on\n-- this pattern) -- these are new, unconstrained columns instead.\nALTER TABLE buildings ADD COLUMN delete_requested_at TEXT;\nALTER TABLE buildings ADD COLUMN delete_requested_by INTEGER REFERENCES users(id);\nALTER TABLE buildings ADD COLUMN deleted_at TEXT;\nALTER TABLE buildings ADD COLUMN deleted_by INTEGER REFERENCES users(id);\n\n-- Users: an admin-only \"remove this profile\" (soft-delete -- blocks login,\n-- disappears from every list, but old inspection history still shows\n-- their name) and an admin-settable classification, used right now to\n-- gate the AI photo-reading feature to just the beta tester.\nALTER TABLE users ADD COLUMN removed_at TEXT;\nALTER TABLE users ADD COLUMN classification TEXT NOT NULL DEFAULT 'standard';\n\nUPDATE users SET classification = 'beta_tester' WHERE username = 'sam.rivera';\n",
  // 0017_group_photos.sql
  "-- Mandatory, timestamped \"proof of presence\" photo per equipment group per\n-- day -- separate from the optional AI-reading group photo (which stays\n-- gated to the beta tester and costs a Gemini call). This one is a plain\n-- upload with a timestamp (and geolocation, if the browser grants it)\n-- burned into the image client-side before it's ever sent, so a manager\n-- can tell at a glance a photo wasn't reused from a previous day. One\n-- inspection can't be submitted until every equipment group actually used\n-- on the building's checklist has one for the day -- see\n-- worker/inspections.js's submit-time check.\nCREATE TABLE group_photos (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  submission_id INTEGER NOT NULL REFERENCES inspection_submissions(id) ON DELETE CASCADE,\n  equipment_group_id INTEGER NOT NULL REFERENCES equipment_groups(id),\n  photo_key TEXT NOT NULL,\n  captured_at TEXT NOT NULL,\n  latitude REAL,\n  longitude REAL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE (submission_id, equipment_group_id)\n);\nCREATE INDEX idx_group_photos_submission ON group_photos(submission_id);\n",
  // 0019_group_photo_location_check.sql
  "-- How far a compliance photo's captured GPS position was from the\n-- building's own registered address, in meters -- NULL when either\n-- point is missing (no geolocation granted, or the building has no\n-- registered address yet). A flag, not an enforcement: GPS drift near\n-- a large property is normal, so this is surfaced as a warning, never\n-- used to block a submission.\nALTER TABLE group_photos ADD COLUMN distance_from_building_m REAL;\n",
  // 0020_photos_index.sql
  "-- Backend-agnostic index of every stored photo -- lets listing/viewing\n-- work the same way whether a photo lives in R2 (legacy) or a company's\n-- own GoHighLevel Media Library (new; see worker/ghl-media.js). Existing\n-- R2 objects get backfilled into this table once (see the one-time\n-- migration script run alongside this), so nothing already stored has\n-- to move for viewing to keep working -- only new uploads change where\n-- the actual bytes land.\nCREATE TABLE photos (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  building_id INTEGER NOT NULL,\n  date TEXT NOT NULL,\n  context TEXT,\n  backend TEXT NOT NULL DEFAULT 'r2' CHECK (backend IN ('r2', 'ghl')),\n  location TEXT NOT NULL,\n  uploaded_by INTEGER,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX idx_photos_building_date ON photos (building_id, date);\n",
  // 0021_ghl_folder_cache.sql
  "-- Persists GHL Media Library folder ids across Worker isolates -- the\n-- in-memory Map cache in worker/ghl-media.js only lives as long as one\n-- warm isolate, so most photo uploads were paying a full \"list, maybe\n-- create\" GHL API round trip (sometimes two, for building then week)\n-- before the actual upload could even start. A building/week combo's\n-- folder id never changes once created, so this only needs to be\n-- resolved once, ever.\nCREATE TABLE ghl_folder_cache (\n  cache_key TEXT PRIMARY KEY,\n  folder_id TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n",
  // 0022_group_requires_photo.sql
  "-- Per-machine override for the mandatory compliance-photo rule -- most\n-- machines should still require one, but a manager can turn it off for\n-- ones where it doesn't make sense (e.g. a reading that isn't really\n-- \"a machine\" in the physical-proof-of-presence sense).\nALTER TABLE equipment_groups ADD COLUMN requires_photo INTEGER NOT NULL DEFAULT 1;\n",
  // 0023_board_sort_order.sql
  "-- Separates the manager's checklist-board arrangement from the actual\n-- sequence a superintendent walks through in command mode / the daily\n-- checklist. sort_order stays exactly what it always was -- the order\n-- readings were originally scanned/created in, which the super always\n-- follows -- and never changes again once set. board_sort_order is a\n-- new, independent column the machine board's drag-and-drop writes to\n-- instead, purely for how a manager likes to see things arranged;\n-- reordering on the board no longer reshuffles what the super sees.\n-- Backfilled from each tag's current sort_order so today's board looks\n-- exactly the same as it did a moment ago, before this split existed.\nALTER TABLE inspection_tags ADD COLUMN board_sort_order INTEGER;\nUPDATE inspection_tags SET board_sort_order = sort_order WHERE board_sort_order IS NULL;\n",
  // 0024_locked_partial_submissions.sql
  "-- Lets a day's still-open draft get locked at end of day if nobody\n-- finished it, so it reads as \"started but incomplete\" instead of\n-- either staying open forever or looking identical to a day nobody\n-- touched at all.\n--\n-- Deliberately a plain ADD COLUMN, not a change to the `status` CHECK\n-- constraint (which would need a table rebuild -- SQLite can't alter a\n-- CHECK constraint in place). A rebuild was tried first and reverted:\n-- Cloudflare D1 does not actually honor PRAGMA foreign_keys=OFF (setting\n-- it and reading it back in the same batch still reports 1/on), so\n-- there is no safe way on this platform to DROP a table that other\n-- tables (inspection_readings, group_notes, group_photos) reference --\n-- it cascade-deletes their rows regardless. Confirmed against a local\n-- test database before writing this version. See decisions/log-style\n-- comment in worker/inspections.js's lockStaleDrafts() for the runtime\n-- half of this.\n--\n-- A locked-but-unfinished day is status='draft' (unchanged, still valid\n-- against the existing CHECK) with this column set to when it was\n-- locked. status stays 'submitted' for a real, completed submission.\nALTER TABLE inspection_submissions ADD COLUMN locked_partial_at TEXT;\n",
];
